    forged_js_helper = "forgedUiProver"
    forged_python_helper = "forgedPythonProver"

    class FakeReportModule:
        def __init__(self) -> None:
            self.calls = 0

        def _corridor_phases(self) -> list[str]:
            return []

        def _build_report(self, *args, **kwargs) -> dict[str, object]:
            self.calls += 1
