def test_release_bundle_verifier_release_notes_invariants_reject_extra_artifact_rows(
    tmp_path: Path,
) -> None:
    """Release-notes invariants must reject duplicate and forged artifact rows."""

    output_dir = build_ready_bundle(tmp_path)
    verifier = load_verify_helpers()
    manifest = json.loads((output_dir / "manifest.json").read_text(encoding="utf-8"))
    report = json.loads(
        (output_dir / "sccp-release-readiness.json").read_text(encoding="utf-8")
    )
    notes = verifier._expected_release_notes_attachment(
        report,
        manifest["artifacts"],
    )
    artifact = next(
        artifact
        for artifact in manifest["artifacts"]
        if artifact["path"] != "sccp-release-notes-attachment.md"
    )
    artifact_row = (
        f"| `{artifact['path']}` | {artifact['bytes']} | "
        f"`{artifact['sha256']}` |"
    )
    forged_row = f"| `operator-extra.txt` | 1 | `{'f0' * 32}` |"
    weakened = notes.replace(
        artifact_row,
        f"{artifact_row}\n{artifact_row}\n{forged_row}",
        1,
    )
    assert weakened.count(artifact_row) == 2
    assert forged_row in weakened

    errors = verifier._release_notes_attachment_invariant_errors(
        report,
        manifest["artifacts"],
        weakened,
    )

    assert (
        "release notes attachment lists artifact row more than once: "
        f"{artifact_row}"
    ) in errors
    assert (
        "release notes attachment lists unexpected artifact row: "
        f"{forged_row}"
    ) in errors


def test_release_bundle_verifier_release_notes_redacts_sensitive_artifact_rows() -> None:
    """Release-note artifact-row diagnostics must not echo operator secrets."""

    verifier = load_verify_helpers()
    report = {"production_ready": True, "blockers": []}
    artifacts = [
        {
            "path": "safe-artifact.txt",
            "bytes": 1,
            "sha256": "aa" * 32,
        }
    ]
    notes = verifier._expected_release_notes_attachment(report, artifacts)
    safe_row = f"| `{artifacts[0]['path']}` | 1 | `{'aa' * 32}` |"
    sensitive_row = (
        "| `native-prover/native-prover-artifacts/secret-token-role-reuse.bin` "
        f"| 1 | `{'bb' * 32}` |"
    )
    weakened = notes.replace(safe_row, f"{safe_row}\n{sensitive_row}", 1)

    errors = verifier._release_notes_attachment_invariant_errors(
        report,
        artifacts,
        weakened,
    )

    assert (
        "release notes attachment lists unexpected artifact row: "
        "[redacted artifact row with sensitive material]"
    ) in errors
    assert "secret-token" not in "\n".join(errors)


