def test_release_bundle_verifier_classifies_malformed_active_required_record_fields(
    tmp_path: Path,
) -> None:
    """Verifier recomputed checklist must not leak malformed record keys."""

    output_dir = build_ready_bundle(tmp_path)
    verifier = load_verify_helpers()
    report = json.loads(
        (output_dir / "sccp-release-readiness.json").read_text(encoding="utf-8")
    )
    summary_payload = (output_dir / "sccp-all-lanes-summary.json").read_text(
        encoding="utf-8"
    )
    confusable_field = "operat\u043er_override"
    markdown_field = "operator|secret-token"
    cases = (
        (
            " operator_override ",
            "required record summary contains unknown field name with surrounding whitespace",
        ),
        (
            "operator\noverride",
            "required record summary contains unknown field name with control character",
        ),
        (
            "operator override",
            "required record summary contains unknown field name with whitespace",
        ),
        (
            markdown_field,
            "required record summary contains unknown field name with Markdown-unsafe character",
        ),
        (
            confusable_field,
            "required record summary contains unknown field name with non-ASCII character",
        ),
    )

    for field, expected_blocker in cases:
        summary = json.loads(summary_payload)
        active_lane = next(
            lane
            for lane in summary["lanes"]
            if lane["domain"] == verifier.ACTIVE_LAUNCH_DOMAIN
        )
        active_lane["records"][field] = True

        checklist = verifier._active_launch_release_checklist(
            summary,
            report["native_evm_prover_bundle"],
        )
        item_by_id = {item["id"]: item for item in checklist["items"]}
        records_item = item_by_id["all_required_lane_records"]
        blockers = "\n".join(records_item["blockers"])

        assert checklist["ready"] is False, field
        assert records_item["ready"] is False, field
        assert expected_blocker in blockers, field
        assert markdown_field not in blockers
        assert confusable_field not in blockers


def test_release_bundle_verifier_classifies_malformed_active_lane_blockers(
    tmp_path: Path,
) -> None:
    """Verifier recomputed readiness must not hide malformed lane blockers."""

    output_dir = build_ready_bundle(tmp_path)
    verifier = load_verify_helpers()
    report = json.loads(
        (output_dir / "sccp-release-readiness.json").read_text(encoding="utf-8")
    )
    summary_payload = (output_dir / "sccp-all-lanes-summary.json").read_text(
        encoding="utf-8"
    )
    category_item_ids = (
        "governed_deployment_evidence",
        "route_allowlist_binding",
        "live_route_canary_evidence",
    )
    cases = (
        (
            "operator launch hold",
            category_item_ids,
            "domain 1 (eth): active launch lane blockers must be a list of non-empty canonical strings",
        ),
        (
            [123],
            category_item_ids,
            "domain 1 (eth): active launch lane blockers[0] must be a non-empty canonical string",
        ),
        (
            [" padded "],
            category_item_ids,
            "domain 1 (eth): active launch lane blockers[0] must be a non-empty canonical string",
        ),
        (
            ["route canary operator launch hold"],
            ("live_route_canary_evidence",),
            "domain 1 (eth): route canary operator launch hold",
        ),
    )

    for lane_blockers, expected_item_ids, expected_blocker in cases:
        summary = json.loads(summary_payload)
        active_lane = next(
            lane
            for lane in summary["lanes"]
            if lane["domain"] == verifier.ACTIVE_LAUNCH_DOMAIN
        )
        active_lane["blockers"] = lane_blockers

        checklist = verifier._active_launch_release_checklist(
            summary,
            report["native_evm_prover_bundle"],
        )
        item_by_id = {item["id"]: item for item in checklist["items"]}

        assert checklist["ready"] is False, repr(lane_blockers)
        for item_id in expected_item_ids:
            item = item_by_id[item_id]
            assert item["ready"] is False, (repr(lane_blockers), item_id)
            assert expected_blocker in item["blockers"], (
                repr(lane_blockers),
                item_id,
            )
        if not isinstance(lane_blockers, list):
            assert "o" not in item_by_id["live_route_canary_evidence"]["blockers"]


def test_release_bundle_verifier_blocks_malformed_native_prover_blockers(
    tmp_path: Path,
) -> None:
    """Verifier recomputed readiness must not filter malformed native blockers."""

    output_dir = build_ready_bundle(tmp_path)
    verifier = load_verify_helpers()
    report = json.loads(
        (output_dir / "sccp-release-readiness.json").read_text(encoding="utf-8")
    )
    summary = json.loads(
        (output_dir / "sccp-all-lanes-summary.json").read_text(encoding="utf-8")
    )
    cases = (
        (
            "operator override",
            "native EVM prover validation_blockers must be a list of non-empty canonical strings",
            None,
            False,
        ),
        (
            [123],
            "native EVM prover validation_blockers[0] must be a non-empty canonical string",
            None,
            False,
        ),
        (
            [" padded "],
            "native EVM prover validation_blockers[0] must be a non-empty canonical string",
            " padded ",
            True,
        ),
        (
            ["operator\nnative-blocker"],
            "native EVM prover validation_blockers[0] contains control character",
            "operator\nnative-blocker",
            True,
        ),
        (
            ["operator|native-blocker"],
            "native EVM prover validation_blockers[0] contains Markdown-unsafe character",
            "operator|native-blocker",
            True,
        ),
        (
            ["operator native bl\u043ecker"],
            "native EVM prover validation_blockers[0] contains non-ASCII character",
            "operator native bl\u043ecker",
            True,
        ),
        (
            ["operator secret-token-native-blocker"],
            "native EVM prover validation_blockers[0] contains sensitive name",
            "operator secret-token-native-blocker",
            True,
        ),
        (
            ["operator launch hold"],
            "operator launch hold",
            None,
            False,
        ),
    )

    for blocker_value, expected_blocker, forbidden_text, invalid_marker in cases:
        native_bundle = dict(report["native_evm_prover_bundle"])
        native_bundle["validation_blockers"] = blocker_value

        checklist = verifier._active_launch_release_checklist(
            summary,
            native_bundle,
        )
        item_by_id = {item["id"]: item for item in checklist["items"]}
        native_item = item_by_id["native_evm_groth16_prover_bundle"]

        assert checklist["ready"] is False, repr(blocker_value)
        assert native_item["ready"] is False, repr(blocker_value)
        assert expected_blocker in native_item["blockers"]
        assert "o" not in native_item["blockers"]
        assert "secret-token" not in "\n".join(native_item["blockers"])

        tampered_report = dict(report)
        tampered_report["native_evm_prover_bundle"] = native_bundle
        markdown = verifier._expected_readiness_markdown(tampered_report)
        assert verifier._readiness_markdown_invariant_errors(
            tampered_report,
            markdown,
        ) == []
        if invalid_marker:
            assert "`<invalid validation_blockers>`" in markdown
        if forbidden_text is not None:
            assert forbidden_text not in markdown


def test_release_bundle_verifier_rejects_unknown_artifact_fields(
    tmp_path: Path,
) -> None:
    """Manifest and report artifact objects must not carry extra claims."""

    output_dir = build_ready_bundle(tmp_path)
    report_path = output_dir / "sccp-release-readiness.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    report["input_artifacts"][0]["operator_attestation"] = "reviewed elsewhere"
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    rewrite_manifest_artifact(output_dir, "sccp-release-readiness.json")
    rewrite_canonical_report_and_notes(output_dir)

    manifest_path = output_dir / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    for artifact in manifest["artifacts"]:
        if artifact["path"] == "sccp-all-lanes-summary.json":
            artifact["operator_attestation"] = "reviewed elsewhere"
            break
    else:
        raise AssertionError("summary artifact not found")
    manifest_path.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

    verified = subprocess.run(
        ["python3", str(VERIFY_SCRIPT), str(output_dir)],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    assert verified.returncode == 1
    assert (
        "manifest artifact contains unknown field: "
        "operator_attestation"
    ) in verified.stdout
    assert (
        "readiness report input artifact contains unknown field: "
        "operator_attestation"
    ) in verified.stdout


def test_release_bundle_verifier_rejects_malformed_artifact_fields(
    tmp_path: Path,
) -> None:
    """Malformed public artifact fields must be classified before diagnostics."""

    output_dir = build_ready_bundle(tmp_path)
    confusable_field = "operat\u043er_attestation"
    secret_field = "secret_token_artifact_field"
    malformed_fields = {
        " operator_attestation ": "reviewed elsewhere",
        "operator\nattestation": "reviewed elsewhere",
        "operator attestation": "reviewed elsewhere",
        "operator|attestation": "reviewed elsewhere",
        confusable_field: "reviewed elsewhere",
        secret_field: "reviewed elsewhere",
        "operator_attestation": "reviewed elsewhere",
    }

    report_path = output_dir / "sccp-release-readiness.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    report["input_artifacts"][0].update(malformed_fields)
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    rewrite_manifest_artifact(output_dir, "sccp-release-readiness.json")
    rewrite_canonical_report_and_notes(output_dir)

    manifest_path = output_dir / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    for artifact in manifest["artifacts"]:
        if artifact["path"] == "sccp-all-lanes-summary.json":
            artifact.update(malformed_fields)
            break
    else:
        raise AssertionError("summary artifact not found")
    manifest_path.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

    verified = subprocess.run(
        ["python3", str(VERIFY_SCRIPT), str(output_dir)],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    assert verified.returncode == 1
    for label in (
        "manifest artifact",
        "readiness report input artifact",
    ):
        assert (
            f"{label} contains unknown field name with surrounding whitespace"
            in verified.stdout
        )
        assert (
            f"{label} contains unknown field name with control character"
            in verified.stdout
        )
        assert f"{label} contains unknown field name with whitespace" in (
            verified.stdout
        )
        assert (
            f"{label} contains unknown field name with Markdown-unsafe character"
            in verified.stdout
        )
        assert (
            f"{label} contains unknown field name with non-ASCII character"
            in verified.stdout
        )
        assert (
            f"{label} contains unknown field name with sensitive name"
            in verified.stdout
        )
        assert (
            f"{label} contains unknown field: operator_attestation"
            in verified.stdout
        )
    assert confusable_field not in verified.stdout
    assert secret_field not in verified.stdout


def test_release_bundle_verifier_rejects_artifact_field_type_drift(
    tmp_path: Path,
) -> None:
    """Manifest and report artifact hashes must keep canonical JSON types."""

    output_dir = build_ready_bundle(tmp_path)
    report_path = output_dir / "sccp-release-readiness.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    report["input_artifacts"][0]["bytes"] = True
    report["input_artifacts"][0]["sha256"] = {
        "sha256": report["input_artifacts"][0]["sha256"],
    }
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
