def test_release_bundle_verifier_rejects_crypto_evidence_malformed_source_adapter_gate_audit_keys(
    tmp_path: Path,
) -> None:
    """Source-adapter gate audit keys must be schema-classified before semantics."""

    output_dir = build_ready_bundle(tmp_path)
    report_path = output_dir / "sccp-release-readiness.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    active_domain = load_report_module().ACTIVE_LAUNCH_DOMAIN
    row = next(
        row for row in report["cryptographic_evidence"] if row["domain"] == active_domain
    )
    confusable_key = "aud\u0456t_note"
    row["source_adapter_gate_audit_hashes"] = {}
    row["source_adapter_gate_audit_hashes"][" audit_note "] = "0x" + "11" * 32
    row["source_adapter_gate_audit_hashes"]["audit\nnote"] = "0x" + "22" * 32
    row["source_adapter_gate_audit_hashes"]["audit note"] = "0x" + "33" * 32
    row["source_adapter_gate_audit_hashes"]["audit|note"] = "0x" + "44" * 32
    row["source_adapter_gate_audit_hashes"][confusable_key] = "not-a-hex32"
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    rewrite_manifest_artifact(output_dir, "sccp-release-readiness.json")
    rewrite_canonical_report_and_notes(output_dir)

    verified = subprocess.run(
        ["python3", str(VERIFY_SCRIPT), str(output_dir)],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    assert verified.returncode == 1
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with "
        "surrounding whitespace"
    ) in verified.stdout
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with "
        "control character"
    ) in verified.stdout
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with whitespace"
    ) in verified.stdout
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with "
        "Markdown-unsafe character"
    ) in verified.stdout
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with "
        "non-ASCII character"
    ) in verified.stdout
    assert confusable_key not in verified.stdout
    assert (
        "readiness report cryptographic_evidence does not match embedded lane evidence"
        in verified.stdout
    )


def test_release_bundle_verifier_suppresses_crypto_evidence_malformed_markdown_leaks(
    tmp_path: Path,
) -> None:
    """Malformed crypto row domains and audit keys must not leak from Markdown checks."""

    output_dir = build_ready_bundle(tmp_path)
    report_path = output_dir / "sccp-release-readiness.json"
    report = json.loads(report_path.read_text(encoding="utf-8"))
    malformed_domain = "2|operator"
    forged_chain = "forged-crypto-chain"
    domain_row = next(row for row in report["cryptographic_evidence"] if row["domain"] == 2)
    domain_row["domain"] = malformed_domain
    domain_row["chain"] = forged_chain

    active_domain = load_report_module().ACTIVE_LAUNCH_DOMAIN
    active_row = next(
        row for row in report["cryptographic_evidence"] if row["domain"] == active_domain
    )
    malformed_audit_key = "audit|note"
    forged_audit_hash = "0x" + "44" * 32
    active_row["source_adapter_gate_audit_hashes"] = {
        malformed_audit_key: forged_audit_hash,
    }
    report_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    rewrite_manifest_artifact(output_dir, "sccp-release-readiness.json")

    verified = subprocess.run(
        ["python3", str(VERIFY_SCRIPT), str(output_dir)],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

    assert verified.returncode == 1
    assert (
        "readiness report cryptographic evidence row domain must be an integer"
        in verified.stdout
    )
    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains audit field name with "
        "Markdown-unsafe character"
    ) in verified.stdout
    assert malformed_domain not in verified.stdout
    assert forged_chain not in verified.stdout
    assert malformed_audit_key not in verified.stdout
    assert forged_audit_hash not in verified.stdout


def test_release_bundle_verifier_accepts_bsc_testnet_crypto_profile() -> None:
    """BSC testnet crypto rows must bind chain id 97 and testnet route IDs."""

    verifier = load_verify_helpers()
    hex32 = lambda byte: "0x" + byte * 32
    row = {
        "domain": verifier.SCCP_DOMAIN_BSC,
        "chain": "bsc-testnet",
        "evm_source_rpc_chain_id": "97",
        "evm_source_block_tag": "latest",
        "evm_destination_rpc_chain_id": "97",
        "evm_destination_block_tag": "latest",
        "source_verifier_material_hash": hex32("11"),
        "source_adapter_engine_deployment_hash": hex32("22"),
        "destination_binding_hash": hex32("33"),
        "route_allowlist_hash": hex32("44"),
        "route_canary_evidence_hash": hex32("55"),
        "route_canary_evidence_source": "evm_message_proof_accepted_transaction",
        "route_canary_evidence_bound": True,
        "route_canary_transaction_hash": hex32("66"),
        "route_canary_receipt_block_number": 4660,
        "route_canary_receipt_block_hash": hex32("77"),
        "route_canary_receipt_block_finalized": True,
        "route_canary_block_receipts_root": hex32("88"),
        "route_canary_message_id": hex32("99"),
        "route_canary_block_number": None,
        "route_canary_block_timestamp": None,
        "source_adapter_gate_required": False,
        "source_adapter_gate_hash": "",
        "source_adapter_gate_audit_hashes": {},
    }

    assert verifier._cryptographic_evidence_row_schema_errors(row) == []
    assert not any(
        "chain mismatch for domain 2" in error
        for error in verifier._cryptographic_evidence_inventory_errors([row])
    )

    enabled_testnet_gate = {
        **row,
        "source_adapter_gate_required": True,
        "source_adapter_gate_hash": hex32("aa"),
        "source_adapter_gate_audit_hashes": {"evm_source_gate_hash": hex32("aa")},
    }
    assert any(
        "source_adapter_gate_required must be false for this domain" in error
        for error in verifier._cryptographic_evidence_row_schema_errors(
            enabled_testnet_gate
        )
    )

    disabled_mainnet_gate = {
        **row,
        "chain": "bsc",
        "evm_source_rpc_chain_id": "56",
        "evm_destination_rpc_chain_id": "56",
    }
    assert any(
        "source_adapter_gate_required must be true for this domain" in error
        for error in verifier._cryptographic_evidence_row_schema_errors(
            disabled_mainnet_gate
        )
    )

    unknown_bsc_chain = {**disabled_mainnet_gate, "chain": "bsc-preview"}
    assert any(
        "source_adapter_gate_required must be true for this domain" in error
        for error in verifier._cryptographic_evidence_row_schema_errors(
            unknown_bsc_chain
        )
    )
    assert any(
        "chain mismatch for domain 2" in error
        for error in verifier._cryptographic_evidence_inventory_errors(
            [unknown_bsc_chain]
        )
    )

    wrong_chain_id = {**row, "evm_source_rpc_chain_id": "56"}
    assert (
        "readiness report cryptographic evidence row "
        "evm_source_rpc_chain_id must be BSC chain id 97 for bsc-testnet"
    ) in verifier._cryptographic_evidence_row_schema_errors(wrong_chain_id)
    bsc_route_canary_semantic_cases = (
        (
            "route_canary_evidence_source",
            "operator_attestation",
            "route_canary_evidence_source must be evm_message_proof_accepted_transaction",
        ),
        (
            "route_canary_evidence_source",
            " evm_message_proof_accepted_transaction ",
            "route_canary_evidence_source must be a non-empty string",
        ),
        (
            "route_canary_evidence_bound",
            False,
            "route_canary_evidence_bound must be true for finalized EVM route canary evidence",
        ),
        (
            "route_canary_receipt_block_finalized",
            False,
            "route_canary_receipt_block_finalized must be true for finalized EVM route canary evidence",
        ),
        (
            "route_canary_receipt_block_number",
            0,
            "route_canary_receipt_block_number must be a positive integer",
        ),
        (
            "route_canary_receipt_block_number",
            0x1_0000_0000,
            "route_canary_receipt_block_number must be a positive u32 integer",
        ),
    )
    for field, value, expected_error in bsc_route_canary_semantic_cases:
        drifted = {**row, field: value}
        assert any(
            expected_error in error
            for error in verifier._cryptographic_evidence_row_schema_errors(drifted)
        ), field

    mainnet_hash = verifier._canonical_route_allowlist_hash(
        domain=verifier.SCCP_DOMAIN_BSC,
        chain="bsc",
        source_verifier_material_hash=bytes.fromhex("11" * 32),
        source_adapter_engine_deployment_hash=bytes.fromhex("22" * 32),
        destination_binding_hash=bytes.fromhex("33" * 32),
    )
    testnet_hash = verifier._canonical_route_allowlist_hash(
        domain=verifier.SCCP_DOMAIN_BSC,
        chain="bsc-testnet",
        source_verifier_material_hash=bytes.fromhex("11" * 32),
        source_adapter_engine_deployment_hash=bytes.fromhex("22" * 32),
        destination_binding_hash=bytes.fromhex("33" * 32),
    )
    assert mainnet_hash != testnet_hash


def test_release_bundle_verifier_rejects_tron_crypto_profile_block_metadata_drift() -> None:
    """TRON crypto rows must validate public block metadata before active return."""

    verifier = load_verify_helpers()
    row = {field: None for field in verifier.CRYPTOGRAPHIC_EVIDENCE_KEYS}
    row.update(
        {
            "domain": verifier.SCCP_DOMAIN_TRON,
            "chain": "tron",
            "evm_source_rpc_chain_id": "",
            "evm_source_block_tag": "",
            "evm_destination_rpc_chain_id": "",
            "evm_destination_block_tag": "",
            "route_canary_evidence_bound": False,
            "route_canary_receipt_block_finalized": None,
            "route_canary_block_number": 1,
            "route_canary_block_timestamp": 0,
            "source_adapter_gate_required": True,
            "source_adapter_gate_hash": "0x" + "11" * 32,
            "source_adapter_gate_audit_hashes": {
                "tron_dpos_source_gate_hash": "0x" + "11" * 32,
            },
        }
    )

    assert verifier._cryptographic_evidence_row_schema_errors(row) == []
    tron_block_metadata_cases = (
        (
            "route_canary_block_number",
            0,
            "route_canary_block_number must be a positive integer",
        ),
        (
            "route_canary_block_number",
            0x1_0000_0000_0000_0000,
            "route_canary_block_number must be a positive u64 integer",
        ),
        (
            "route_canary_block_timestamp",
            -1,
            "route_canary_block_timestamp must be a non-negative integer",
        ),
        (
            "route_canary_block_timestamp",
            0x1_0000_0000_0000_0000,
            "route_canary_block_timestamp must be a non-negative u64 integer",
        ),
    )
    for field, value, expected_error in tron_block_metadata_cases:
        drifted = {**row, field: value}
        assert any(
            expected_error in error
            for error in verifier._cryptographic_evidence_row_schema_errors(drifted)
        ), field

    non_tron_row = {**row, "domain": verifier.SCCP_DOMAIN_TON, "chain": "ton"}
    errors = verifier._cryptographic_evidence_row_schema_errors(non_tron_row)
    assert any(
        "route_canary_block_number must be null for non-TRON lanes" in error
        for error in errors
    )
    assert any(
        "route_canary_block_timestamp must be null for non-TRON lanes" in error
        for error in errors
    )


def test_release_bundle_verifier_rejects_crypto_source_adapter_gate_policy_drift() -> None:
    """Non-active public crypto rows must enforce source-adapter gate policy."""

    verifier = load_verify_helpers()
    row = {field: None for field in verifier.CRYPTOGRAPHIC_EVIDENCE_KEYS}
    row.update(
        {
            "domain": verifier.SCCP_DOMAIN_SOL,
            "chain": "solana",
            "evm_source_rpc_chain_id": "",
            "evm_source_block_tag": "",
            "evm_destination_rpc_chain_id": "",
            "evm_destination_block_tag": "",
            "route_canary_evidence_bound": False,
            "route_canary_receipt_block_finalized": None,
            "source_adapter_gate_required": False,
            "source_adapter_gate_hash": "0x" + "11" * 32,
            "source_adapter_gate_audit_hashes": {
                "operator_override": "0x" + "11" * 32,
            },
        }
    )

    false_required_errors = verifier._cryptographic_evidence_row_schema_errors(row)

    assert any(
        "source_adapter_gate_required must be true for this domain" in error
        for error in false_required_errors
    )
    assert any(
        "source_adapter_gate_hash must be empty when gate is not required" in error
        for error in false_required_errors
    )
    assert any(
        "source_adapter_gate_audit_hashes must be empty when gate is not required"
        in error
        for error in false_required_errors
    )

    required_row = {
        **row,
        "source_adapter_gate_required": True,
        "source_adapter_gate_hash": "0x" + "22" * 32,
        "source_adapter_gate_audit_hashes": {
            "operator_override": "0x" + "22" * 32,
            "solana_full_light_client_gate_hash": "0x" + "33" * 32,
        },
    }
    required_errors = verifier._cryptographic_evidence_row_schema_errors(required_row)

    assert any(
        "source_adapter_gate_audit_hashes contains unexpected field: operator_override"
        in error
        for error in required_errors
    )
    assert any(
        "source_adapter_gate_audit_hashes missing field: "
        "solana_tower_replay_verifier_hash" in error
        for error in required_errors
    )
    assert any(
        "source_adapter_gate_hash must match "
        "source_adapter_gate_audit_hashes.solana_full_light_client_gate_hash" in error
        for error in required_errors
    )


def test_release_bundle_verifier_redacts_sensitive_source_adapter_gate_audit_fields() -> None:
    """Unexpected source-gate audit fields must not leak secret-like names."""

    verifier = load_verify_helpers()
    expected_audit_hashes = {
        "solana_tower_replay_verifier_hash": "0x" + "61" * 32,
        "solana_full_accountsdb_lattice_verifier_hash": "0x" + "62" * 32,
        "solana_bank_fork_choice_verifier_hash": "0x" + "63" * 32,
        "solana_full_light_client_gate_hash": "0x" + "64" * 32,
    }
    row = {field: None for field in verifier.CRYPTOGRAPHIC_EVIDENCE_KEYS}
    row.update(
        {
            "domain": verifier.SCCP_DOMAIN_SOL,
            "chain": "solana",
            "evm_source_rpc_chain_id": "",
            "evm_source_block_tag": "",
            "evm_destination_rpc_chain_id": "",
            "evm_destination_block_tag": "",
            "route_canary_evidence_bound": False,
            "route_canary_receipt_block_finalized": None,
            "source_adapter_gate_required": True,
            "source_adapter_gate_hash": expected_audit_hashes[
                "solana_full_light_client_gate_hash"
            ],
            "source_adapter_gate_audit_hashes": {
                **expected_audit_hashes,
                "secret-token-audit-field": "0x" + "65" * 32,
            },
        }
    )

    crypto_errors = "\n".join(verifier._cryptographic_evidence_row_schema_errors(row))

    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains unexpected field with "
        "sensitive name"
    ) in crypto_errors
    assert "secret-token-audit-field" not in crypto_errors

    safe_row = {
        **row,
        "source_adapter_gate_audit_hashes": {
            **expected_audit_hashes,
            "operator_override": "0x" + "65" * 32,
        },
    }
    safe_crypto_errors = "\n".join(
        verifier._cryptographic_evidence_row_schema_errors(safe_row)
    )

    assert (
        "readiness report cryptographic evidence row "
        "source_adapter_gate_audit_hashes contains unexpected field: "
        "operator_override"
    ) in safe_crypto_errors

    lane = {
        "domain": verifier.SCCP_DOMAIN_SOL,
        "chain": "solana",
        "source_record_hashes": {
            "source_verifier_material_hash": "0x" + "71" * 32,
            "source_adapter_engine_deployment_hash": "0x" + "72" * 32,
        },
        "destination_binding": {
            "destination_binding_hash": "0x" + "73" * 32,
        },
        "route_allowlist": {
            "route_allowlist_hash": "0x" + "74" * 32,
            "route_canary": {
                "evidence_hash": "0x" + "75" * 32,
            },
        },
    }
    source_gate = {
        "required": True,
        "ready": True,
        "gate_hash": expected_audit_hashes["solana_full_light_client_gate_hash"],
        "audit_hashes": {
            **expected_audit_hashes,
            "secret-token-audit-field": "0x" + "65" * 32,
        },
        "blockers": [],
    }
    gate_label = "readiness report embedded evidence lane domain 3 source_adapter_gate"
    gate_errors = "\n".join(
        verifier._source_adapter_gate_coherence_errors(
            gate_label,
            lane,
            source_gate,
        )
    )

    assert (
        f"{gate_label} audit_hashes contains unexpected field with sensitive name"
        in gate_errors
    )
    assert "secret-token-audit-field" not in gate_errors

    safe_source_gate = {
        **source_gate,
        "audit_hashes": {
            **expected_audit_hashes,
            "operator_override": "0x" + "65" * 32,
        },
    }
    safe_gate_errors = "\n".join(
        verifier._source_adapter_gate_coherence_errors(
            gate_label,
            lane,
            safe_source_gate,
        )
    )

    assert (
        f"{gate_label} audit_hashes contains unexpected field: operator_override"
        in safe_gate_errors
    )


