        required_markers = next(
            markers
            for path, markers in verifier.SCCP_SOURCE_MATERIAL_ROLE_VALIDATION_MARKERS
            if path == inventory_path
        )
        sparse_source = tmp_path / f"all-lanes-{Path(inventory_path).name}"
